function recomputeSectorCenters(width, height) {
  const sectors = SECTOR_ORDER.filter((s) => s in SECTOR_COLORS);
  const count = sectors.length;
  const padding = 80;
  const usableW = Math.max(120, width - padding * 2);
  const usableH = Math.max(120, height - padding * 2);
  const cols = Math.ceil(Math.sqrt(count));
  const rows = Math.ceil(count / cols);
  const cellW = usableW / Math.max(1, cols - 1 || 1);
  const cellH = usableH / Math.max(1, rows - 1 || 1);
  sectors.forEach((sector, i) => {
    const r = Math.floor(i / cols);
    const c = i % cols;
    state.sectorCenters[sector] = {
      x: padding + (cols === 1 ? 0 : c * cellW),
      y: padding + (rows === 1 ? 0 : r * cellH)
    };
  });
}

input.newString:
function recomputeSectorCenters(width, height) {
  const sectors = SECTOR_ORDER.filter((s) => s in SECTOR_COLORS);
  const cx = width / 2;
  const cy = height / 2;
  const radius = Math.min(width, height) * 0.18;
  const angleOffset = -Math.PI / 2;
  sectors.forEach((sector, i) => {
    const angle = angleOffset + (2 * Math.PI * i) / sectors.length;
    state.sectorCenters[sector] = {
      x: cx + Math.cos(angle) * radius,
      y: cy + Math.sin(angle) * radius
    };
  });
}

