  .force("collide", d3.forceCollide().radius((d) => d.radius + 2).iterations(3))
  .force("x", d3.forceX((d) => state.sectorCenters[d.sector].x).strength(0.32))
  .force("y", d3.forceY((d) => state.sectorCenters[d.sector].y).strength(0.32))
  .force("center", d3.forceCenter(state.width / 2, state.height / 2))
  .stop();

for (let i = 0; i < 500; i++) simulation.tick();
runSimulation(simulation, nodes);

